import ast


class Node:
    def __init__(self, node):
        self.node = node
        self.classes = []
        self.functions = []

    def scan_nodes(self):
        yield self
        for child in ast.iter_child_nodes(self.node):
            if isinstance(child, ast.FunctionDef):
                yield from FunctionNode(child).scan_nodes()
            elif isinstance(child, ast.ClassDef):
                yield from ClassNode(child).scan_nodes()
            else:
                yield from Node(child).scan_nodes()

    def to_str(self):
        if isinstance(self.node, ast.Attribute):
            return str(self.node.value.id)
        if isinstance(self.node, ast.Constant):
            return str(self.node.value)
        if isinstance(self.node, ast.Name):
            return str(self.node.id)
        return None


class NamedNode(Node):
    def __init__(self, node, name=None):
        super().__init__(node)
        self.name = name
        self.classes = []
        self.functions = []

    def scan_nodes(self):
        for node in super().scan_nodes():
            if isinstance(node, FunctionNode):
                self.functions.append(node)
            elif isinstance(node, ClassNode):
                self.classes.append(node)
        yield self
        for node in super().scan_nodes():
            if not isinstance(node, (FunctionNode, ClassNode)):
                yield node


class AttributeNode(NamedNode):
    def __init__(self, node):
        super().__init__(node, name=node.name)


class ClassNode(NamedNode):
    def __init__(self, node):
        super().__init__(node, name=node.name)
        self.parents = [
            parent.id for parent in node.bases if isinstance(parent, ast.Name)
        ]

    def to_str(self):
        inheritance_string = ""
        if self.parents:
            inheritance_string = f"({', '.join(self.parents)})"
        return (
            f"CLASS {self.name}"
            + inheritance_string
            + "\n"
            + "\n".join(
                ("  " + function.to_str() for function in self.functions)
            )
        )


class FunctionNode(NamedNode):
    def __init__(self, node):
        super().__init__(node, name=node.name)
        self.args = [arg.arg for arg in node.args.args]
        # print("args", node.args.args)
        # print("defaults", node.args.defaults)
        # print("kw_defaults", node.args.kw_defaults)
        # print("kwarg", node.args.kwarg)
        # print("kwonlyargs", node.args.kwonlyargs)
        # print("posonlyargs", node.args.posonlyargs)
        # print("vararg", node.args.vararg)
        self.decorators = [
            deco.id
            for deco in node.decorator_list
            if isinstance(deco, ast.Name)
        ]
        self.returns = None
        if node.returns:
            self.returns = Node(node.returns).to_str()

    def to_str(self):
        decostring = []
        for deco in self.decorators:
            # print(f"  @{deco}")
            decostring += [f"{deco}"]
        if decostring:
            decostring = f"<<{', '.join(decostring)}>> "
        else:
            decostring = ""
        returns_string = ""
        if self.returns:
            returns_string = f" -> {self.returns}"
        return f"def {decostring}{self.name}({', '.join(self.args)}){returns_string}"


def scan_document(filename):
    with open(filename, "r") as file:
        tree = ast.parse(file.read())

    main = Node(tree)

    ret = []

    for node in main.scan_nodes():
        if isinstance(node, FunctionNode):
            ret.append(node.to_str())
            ret.append("")
        if isinstance(node, ClassNode):
            ret.append(node.to_str())
            ret.append("")

    return "\n".join(ret)


if __name__ == "__main__":
    print(scan_document("keymap.py"))
